PythonTypeScriptJavaC# <pre><code>from conductor.ai.agents import Agent, AgentRuntime, tool

@tool
def get_weather(city: str) -&gt; str:
    """Get current weather for a city."""
    return f"72°F and sunny in {city}"

agent = Agent(
    name="weatherbot",
    model="openai/gpt-4o",
    instructions="You are an outdoor activity assistant. Look up the weather, then recommend activities.",
    tools=[get_weather],
)

with AgentRuntime() as runtime:
    result = runtime.run(agent, "What should I do today in NYC?")
    result.print_result()
</code></pre> <pre><code>import { Agent, AgentRuntime, tool } from '@conductor-oss/conductor-agent-sdk';

const getWeather = tool(
  async ({ city }: { city: string }) =&gt; `72°F and sunny in ${city}`,
  { name: 'get_weather', description: 'Get current weather for a city',
    inputSchema: { type: 'object', properties: { city: { type: 'string' } }, required: ['city'] } }
);

const agent = new Agent({
  name: 'weatherbot',
  model: 'openai/gpt-4o',
  instructions: 'You are an outdoor activity assistant. Look up the weather, then recommend activities.',
  tools: [getWeather],
});

const runtime = new AgentRuntime();
const result = await runtime.run(agent, 'What should I do today in NYC?');
result.printResult();
await runtime.shutdown();
</code></pre> <pre><code>import org.conductoross.conductor.ai.Agent;
import org.conductoross.conductor.ai.AgentRuntime;
import org.conductoross.conductor.ai.tool.Tool;

public class Weatherbot {

    @Tool(description = "Get current weather for a city")
    public String getWeather(String city) {
        return "72°F and sunny in " + city;
    }

    public static void main(String[] args) throws Exception {
        Weatherbot wb = new Weatherbot();

        Agent agent = Agent.builder()
            .name("weatherbot")
            .model("openai/gpt-4o")
            .instructions("You are an outdoor activity assistant. Look up the weather, then recommend activities.")
            .tools(wb)
            .build();

        try (AgentRuntime runtime = new AgentRuntime()) {
            var result = runtime.run(agent, "What should I do today in NYC?");
            System.out.println(result.getOutput());
        }
    }
}
</code></pre> <pre><code>using Conductor.AI;

var agent = new Agent(new AgentConfig {
    Name = "weatherbot",
    Model = "openai/gpt-4o",
    Instructions = "You are an outdoor activity assistant. Look up the weather, then recommend activities.",
    Tools = [
        Tool.From((string city) =&gt; $"72°F and sunny in {city}",
            name: "get_weather",
            description: "Get current weather for a city")
    ]
});

await using var runtime = new AgentRuntime();
var result = await runtime.RunAsync(agent, "What should I do today in NYC?");
Console.WriteLine(result.Output);
</code></pre> <p>Open http://localhost:6767 to see the execution in the visual UI.</p>

